from build123d import *
import math

base = Box(50, 50, 50)
cyl = Cylinder(2.5, 50 * math.sqrt(2))

part = base + cyl
for i in range(1, 3):
    part = part + Rot(0, 0, i * 90) * cyl
for i in range(1, 3):
    part = part + Rot(0, i * 90, 0) * cyl
for i in range(1, 3):
    part = part + Rot(i * 90, 0, 0) * cyl
for i in range(1, 3):
    part = part + Rot(0, i * 90, 45) * cyl
for i in range(1, 3):
    part = part + Rot(i * 90, 0, 45) * cyl
for i in range(1, 3):
    part = part + Rot(0, i * 90, -45) * cyl
for i in range(1, 3):
    part = part + Rot(i * 90, 0, -45) * cyl

part.name = "box_with_cylinders"
export_step(part, "output.step")
